INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N050-01','CN0248','S050-01','分股水量及类比水质','3.7.2 表3.6-3/4，7.2.2','物理及三次化学洗各1800.9m³/a；混合7204m³/a表列，26m³/d站及24m³/d设计进水。原水水质类比广东新盈信，非新疆德创实测。表3.6-3量为t/a，正文m³/a；表3.6-4出水7204为处理回用核算，原文另有生产水纳管甚至绍兴污水厂错误地名。以正式批复生产冷凝回用为优先，不把异文解释为实际外排。RO产水和浓水去向须核，不据文字强行画全量蒸发。截图失败。','WEB_PRIMARY','公开正文/检索摘录；PDF截图失败','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N050-02','CN0248','S050-02','正式危废许可','公告〔2024〕30号','6502040138，2024-09-24至2029-09-23，HW50 772-007-50 10000t/a；克拉玛依白碱滩高新区再生资源循环经济产业园。非实际经营量或污水验收。','WEB_PRIMARY','公开正文/检索摘录；PDF截图失败','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N050-03','CN0070','S027-01','八股源强及设计出水','表3.8-6、7.2-2，7.2.2','物理32400、化学515.2、漂洗15200、活化1000、吸收1300、地洗507.12、制水4368、生活720m³/a；活化钒3600mg/L、COD20000，物理SS6000、吸收盐11000均设计。站300m³/d、169.74m³/d进站既有，不重复；出水为设计控制限值，非实际。物理泥350t/a含水率60%设计；生物膜接触氧化不是分离膜。截图失败。','WEB_PRIMARY','公开正文/检索摘录；PDF截图失败','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N050-04','CN0070','S050-03','现场生产状态','2026-11政府网站现场报道','现场见废剂进厂及物理清灰、化学漂洗等生产活动，项目2万m³/a处置能力，投资8539.94万元全项目。报道约2000万元为相关企业处置采购成本节约，非污水运行费用；邻厂氯化钙造粒属于湘晟，绝不归华电。未核污水实际链或膜。','WEB_PRIMARY','公开正文/检索摘录；PDF截图失败','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N050-05','CN0234','S050-04','正式批复及名称异文','平环审〔2025〕3号第1及4条','拟审批称锦壕，正式文件称锦壤，同址同项目4万吨，保留原主体及异名待工商核实；两条2万吨线。离子交换回球磨、结晶母液回除杂，湿法尾液精滤四效蒸发回生产，析硫酸钠；公辅、经中和的废气处理水、生活水外排。污水站沉渣危废。非实际。截图失败。','WEB_PRIMARY','公开正文/检索摘录；PDF截图失败','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N050-06','CN0097','S050-06','安徽基地规模和状态','官网迅凯简介','公司称安徽生产基地2023建成投产，年产能11000吨，含雷尼合金、镍铜贵金属、载体；总投资1.8亿元、45亩，非污水专款；未取实际量及水工艺。','WEB_COMPANY','公开正文/检索摘录；PDF截图失败','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N050-07','CN0084','S050-09','处罚证据范围','沪0100环罚〔2026〕18号','公司超过载明许可排放浓度处罚摘要，未明确污染物、排口、工艺及具体项目，不当作贵金属催化剂废水证据或判断膜。','WEB_PRIMARY','公开正文/检索摘录；PDF截图失败','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N050-08','CN0245','S050-10','钠盐回收技术线索','2026-07-15专利新闻','报道共沉淀催化剂生产废水除重金属、分段蒸发结晶回收钠盐；专利不等于实际工厂采用，不入事实图。','WEB_SECONDARY','公开正文/检索摘录；PDF截图失败','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N050-09','CN0278','S050-11','环评索引复查','检索摘录','低碳烯烃催化剂制备项目环评索引出现过滤器名称，不能认定为污水膜或运行；无新站工艺。','WEB_SECONDARY','公开正文/检索摘录；PDF截图失败','2026-11-28');
